structure.mermaidSource:
flowchart TD
  start(["Início: Identificar Verbo e Complemento"]) --> proc_isolar["Isolar forma verbal e testar com 'o menino'"]
  proc_isolar --> dec_resultado{"Qual a junção sintática com 'o menino'?"}
  dec_resultado -- "Deu 'o menino' (Sem preposição)" --> dec_vtdi_od{"O verbo é bitransitivo (VTDI) com outro complemento já expresso?"}
  dec_resultado -- "Deu 'ao menino' (Com preposição 'a')" --> dec_vtdi_oi{"O verbo é bitransitivo (VTDI) com outro complemento já expresso?"}
  dec_vtdi_od -- "Não (Monotransitivo)" --> res_vtd["VTD Monotransitivo: Selecionar O, A, OS, AS (ou -lo, -no)"]
  dec_vtdi_od -- "Sim (Bitransitivo)" --> res_vtdi_od["VTDI: Termo é Objeto Direto (O, A, OS, AS) | Outro termo deve ser O.I."]
  dec_vtdi_oi -- "Não (Monotransitivo)" --> res_vti["VTI Monotransitivo: Selecionar LHE, LHES (ou pronome preposicionado)"]
  dec_vtdi_oi -- "Sim (Bitransitivo)" --> res_vtdi_oi["VTDI: Termo é Objeto Indireto (LHE, LHES) | Outro termo deve ser O.D."]

flowchart TD
  start_vtdi["Início: Segmento com verbo potencialmente bitransitivo"] --> proc_isolar["Isolar o verbo regente e os dois complementos oracionais/nominais"]
  proc_isolar --> dec_regente{"O verbo opera como VTDI no contexto examinado?"}
  dec_regente -- "Não" --> res_univalente["Desvio de premissa: Verbo atua como VTD, VTI ou VI. Encaminhar para análise de regência monocomplementar."]
  dec_regente -- "Sim" --> dec_c1{"O Complemento 1 é introduzido por preposição regida?"}
  dec_c1 -- "Não (Sem preposição)" --> dec_c2_after_od{"O Complemento 2 é introduzido por preposição regida?"}
  dec_c1 -- "Sim (Com preposição)" --> dec_c2_after_oi{"O Complemento 2 é introduzido por preposição regida?"}
  dec_c2_after_od -- "Não (Sem preposição)" --> res_duplo_od["BLOQUEIO ATIVADO: Duplo Objeto Direto (OD + OD). Construção agramatical na norma culta. Exige preposicionamento de um dos termos."]
  dec_c2_after_od -- "Sim (Com preposição)" --> dec_prep_od_oi{"A preposição empregada é canônica para o verbo e livre de correlações proibidas?"}
  dec_c2_after_oi -- "Sim (Com preposição)" --> res_duplo_oi["BLOQUEIO ATIVADO: Duplo Objeto Indireto (OI + OI). Construção agramatical na norma culta. Exige eliminação da preposição de um dos termos."]
  dec_c2_after_oi -- "Não (Sem preposição)" --> dec_prep_oi_od{"A preposição empregada no Complemento 1 é canônica para o verbo?"}
  dec_prep_od_oi -- "Sim" --> res_valido_od_oi["CONSTRUÇÃO VÁLIDA: Assimetria canônica respeitada (OD + OI). Sintaxe de regência plenamente homologada."]
  dec_prep_od_oi -- "Não" --> res_prep_invalida_od["BLOQUEIO REGAL: Assimetria presente, porém a preposição é ilegítima ou contém correlação vedada (ex.: preferir... do que). Rejeitar."]
  dec_prep_oi_od -- "Sim" --> res_valido_oi_od["CONSTRUÇÃO VÁLIDA: Assimetria canônica respeitada em ordem inversa (OI + OD). Sintaxe de regência plenamente homologada."]
  dec_prep_oi_od -- "Não" --> res_prep_invalida_oi["BLOQUEIO REGAL: Assimetria presente, porém a preposição do regente está incorreta na norma culta. Rejeitar."]
